use rustomp_dsp::{AC127, GND, Netlist};

/// 总下标数（`Netlist<N>` 的 N；包含排在最后的固定电位节点）
pub const N: usize = 11;

/// LU 真正要处理的未知量个数（固定节点排在它之后，行列全零）
pub const UNKNOWNS: usize = 9;

/// 实时路径的牛顿迭代次数（`* @rustomp newton=` 指定；默认 3）

/// 2 次不够：方波/快速边沿下会欠收敛 → 次谐波极限环（DEVLOG E50）。
pub const NEWTON_ITERS: usize = 3;

/// 可调参数（电位器位置 0..1 / 开关布尔）。
#[derive(Clone, Copy, PartialEq)]
pub struct Params {
    pub p1: f64,
    pub p2: f64,
}

impl Default for Params {
    fn default() -> Self {
        Self {
            p1: 0.5,
            p2: 0.5,
        }
    }
}

